public:
    HttpClient(ConnectionPool* pool) {}
};

class TaxRateProvider {
public:
    TaxRateProvider(HttpClient* client) {}
};

class PricingEngine {
public:
    PricingEngine(TaxRateProvider* tax, CurrencyConverter* currency) {}
    // no idea, and no need to know, what TaxRateProvider or CurrencyConverter need internally
};

class OrderService {
public:
    OrderService(OrderRepository* repository, PricingEngine* pricing) {}
};

// Boost.DI reads all these constructor signatures at startup, builds the graph,
// determines the correct order on its own, and constructs everything, no composition root function exists
